-- Fullblood case seed INSERT SQL (idempotent)
-- Execute in MySQL 8.0+.
-- Target: recreate one product + one device + two rules (full-model rule + action rule).

SET NAMES utf8mb4;

SET @tenant_id = 1;
SET @creator = '1';
SET @updater = '1';

SET @product_key = 'AUTO_FULLBLOOD_SEED_V1';
SET @product_name = 'AutoFullbloodSeedV1';
SET @device_dn = 'AUTO-FULLBLOOD-SEED-DN-V1';
SET @device_name = 'AutoFullbloodSeedDeviceV1';
SET @serial_no = 'AUTOFULLBLOODSEED000000000000000001';
SET @product_secret = 'fullbloodseedv1secret000000000000';

SET @rule_name_full = 'AUTO_FULLBLOOD_RULE_SEED_V1';
SET @rule_name_action = 'AUTO_ACTION_RULE_SEED_V1';

-- Full thing-model JSON (base64 encoded, decoded at insert time)
SET @model_b64 = '';

-- Rule configs (base64 encoded)
SET @r34_listeners_b64 = '';
SET @r34_filters_b64 = '';
SET @r34_actions_b64 = 'W10='; -- []
SET @r34_trigger_b64 = 'eyJtaW5JbnRlcnZhbFNlYyI6MCwiZGVsYXlTZWMiOjAsImVuYWJsZUFsZXJ0UmVjb3ZlciI6ZmFsc2UsInJlY292ZXJRdWlldFNlYyI6MH0=';

SET @r36_listeners_b64 = '';
SET @r36_filters_b64 = '';
SET @r36_actions_b64 = '';
SET @r36_trigger_b64 = 'eyJtaW5JbnRlcnZhbFNlYyI6MCwiZGVsYXlTZWMiOjAsImVuYWJsZUFsZXJ0UmVjb3ZlciI6ZmFsc2UsInJlY292ZXJRdWlldFNlYyI6MH0=';

SET @now = NOW();
SET @category_id = (
  SELECT id FROM eiot_category
  WHERE tenant_id = @tenant_id AND deleted = b'0'
  ORDER BY id LIMIT 1
);
SET @category_id = IFNULL(@category_id, 1);

-- Clean old seeded data
DELETE FROM eiot_rule_info
WHERE tenant_id = @tenant_id AND deleted = b'0'
  AND name IN (@rule_name_full, @rule_name_action);

DELETE FROM eiot_device_info
WHERE tenant_id = @tenant_id AND deleted = b'0'
  AND product_key = @product_key
  AND dn = @device_dn;

DELETE FROM eiot_thing_model
WHERE tenant_id = @tenant_id AND deleted = b'0'
  AND product_key = @product_key;

DELETE FROM eiot_product
WHERE tenant_id = @tenant_id AND deleted = b'0'
  AND product_key = @product_key;

-- Insert product
INSERT INTO eiot_product (
  name, category_id, product_key, mcu_code, remark1, img_url, remark, status,
  creator, create_time, updater, update_time, deleted, tenant_id,
  node_type, protocol_code, keep_alive_time, product_secret, transparent, locate_type
) VALUES (
  @product_name, @category_id, @product_key, '',
  'fullblood seed product (all data types)',
  '', 'seeded by fullblood-case-seed-insert.sql', 0,
  @creator, @now, @updater, @now, b'0', @tenant_id,
  0, 'GB28181', 120, @product_secret, b'0', 0
);

-- Insert thing model
INSERT INTO eiot_thing_model (
  creator, create_time, updater, update_time, deleted, tenant_id, product_key, model
) VALUES (
  @creator, @now, @updater, @now, b'0', @tenant_id, @product_key,
  CONVERT(FROM_BASE64(@model_b64) USING utf8mb4)
);

-- Insert device
INSERT INTO eiot_device_info (
  dn, product_key, dept_id, properties, creator, create_time, updater, update_time,
  deleted, tenant_id, name, state, offline_time, online_time, serial_no, remark,
  lat, lon, model, parent_id, active_time, secret, firm_version, addr, transparent, node_type
) VALUES (
  @device_dn, @product_key, 0, NULL, @creator, @now, @updater, @now,
  b'0', @tenant_id, @device_name, 0, NULL, NULL, @serial_no, NULL,
  NULL, NULL, 'M1', NULL, NULL, NULL, '1.0.0', NULL, b'0', 0
);

-- Insert rule #1: full-model match
INSERT INTO eiot_rule_info (
  name, listeners, filters, actions, trigger_options, typ, state, remark,
  creator, create_time, updater, update_time, deleted, tenant_id, dept_id
) VALUES (
  @rule_name_full,
  CONVERT(FROM_BASE64(@r34_listeners_b64) USING utf8mb4),
  CONVERT(FROM_BASE64(@r34_filters_b64) USING utf8mb4),
  CONVERT(FROM_BASE64(@r34_actions_b64) USING utf8mb4),
  CONVERT(FROM_BASE64(@r34_trigger_b64) USING utf8mb4),
  'scene', 1, 'fullblood all-types rule',
  @creator, @now, @updater, @now, b'0', @tenant_id, 0
);

-- Insert rule #2: action trigger
INSERT INTO eiot_rule_info (
  name, listeners, filters, actions, trigger_options, typ, state, remark,
  creator, create_time, updater, update_time, deleted, tenant_id, dept_id
) VALUES (
  @rule_name_action,
  CONVERT(FROM_BASE64(@r36_listeners_b64) USING utf8mb4),
  CONVERT(FROM_BASE64(@r36_filters_b64) USING utf8mb4),
  CONVERT(FROM_BASE64(@r36_actions_b64) USING utf8mb4),
  CONVERT(FROM_BASE64(@r36_trigger_b64) USING utf8mb4),
  'scene', 1, 'fullblood action rule',
  @creator, @now, @updater, @now, b'0', @tenant_id, 0
);

-- Result check
SELECT id, name, product_key, protocol_code, keep_alive_time
FROM eiot_product WHERE product_key = @product_key AND tenant_id = @tenant_id AND deleted = b'0';

SELECT id, product_key, LEFT(model, 120) AS model_preview
FROM eiot_thing_model WHERE product_key = @product_key AND tenant_id = @tenant_id AND deleted = b'0';

SELECT id, dn, product_key, state, serial_no
FROM eiot_device_info WHERE product_key = @product_key AND dn = @device_dn AND tenant_id = @tenant_id AND deleted = b'0';

SELECT id, name, typ, state
FROM eiot_rule_info
WHERE name IN (@rule_name_full, @rule_name_action)
  AND tenant_id = @tenant_id AND deleted = b'0'
ORDER BY id;

